/* Signature Signature Unified Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Solarem": "From sol (sun) + arem (bringer): 'bringer of sun'.", "Lunavem": "From luna (moon) + vem (singer): 'singer of moon'.", "Terralon": "From terra (earth) + lon (keeper): 'keeper of earth'.", "Aqvamir": "From aqva (water) + mir (peace): 'peaceful water'.", "Stellara": "From stella (star) + ara (altar): 'star altar'.", "Venturel": "From vent (wind) + urel (messenger): 'wind messenger'.", "Solarem-dor": "Signature lineage marker: 'house of the sun-bringer'.", "Lunavem-dor": "Signature lineage marker: 'house of the moon-singer'.", "Terralon-dor": "Signature lineage marker: 'house of the earth-keeper'.", "Aqvamir-dor": "Signature lineage marker: 'house of peaceful water'."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Solarem';
console.log(lookup(q));

